       />
       <FilterPills
         onSelect={(value) => {
           setSelectedTab(value);
           if (value === "closures") {
             router.navigate("/admin/closures");
           } else {
             router.navigate("/admin");
           }
         }}
         options={options}
         selected={selectedTab}
       />

       {selectedTab === "publications" ? (
         publications.length ? (
           <View style={styles.list}>
             {publications.map((alert) => (
               <IssueCard alert={alert} key={alert.id}>
                 <View style={styles.actions}>
                   <PrimaryButton
                     label="Declinar"
                     onPress={() => moderateAlert(alert.id, false)}
                     variant="danger"
                   />
                   <PrimaryButton
                     label="Es válida"
                     onPress={() => moderateAlert(alert.id, true)}
                   />
                 </View>
               </IssueCard>
             ))}
           </View>
         ) : (
           <EmptyState>Ya revisaste todas las publicaciones.</EmptyState>
         )
       ) : closures.length ? (
         <View style={styles.list}>
           {closures.map((alert) => (
             <IssueCard
               alert={alert}
               key={alert.id}
               onPress={() =>
                 router.navigate({
