         del encargado.
       </InfoBanner>
       {alert.status === "awaiting_review" ? (
         <View style={styles.actions}>
           <PrimaryButton
             label="Aprobar y dar puntos"
             onPress={() => handleReview(true)}
           />
           <PrimaryButton
             label="Rechazar cierre"
             onPress={() => handleReview(false)}
             variant="danger"
           />
         </View>
       ) : (
