 type PrimaryButtonProps = {
   label: string;
   onPress: () => void;
   disabled?: boolean;
   variant?: "primary" | "outline" | "danger";
 };

 export function PrimaryButton({
   label,
   onPress,
   disabled = false,
   variant = "primary",
 }: PrimaryButtonProps) {
   const buttonStyle =
     variant === "outline"
       ? styles.outline
       : variant === "danger"
         ? styles.danger
         : styles.button;
   const labelStyle =
     variant === "outline"
       ? styles.outlineLabel
       : variant === "danger"
         ? styles.dangerLabel
         : styles.label;
   const pressedStyle =
     variant === "primary" ? styles.pressed : styles.secondaryPressed;

   return (
     <Pressable
       accessibilityRole="button"
       disabled={disabled}
       onPress={onPress}
       style={({ pressed }) => [
         buttonStyle,
         pressed && !disabled ? pressedStyle : null,
         disabled ? styles.disabled : null,
       ]}
     >
       <Text style={labelStyle}>{label}</Text>
     </Pressable>
   );
 }

