    throw new Error(`Push token ${pushToken} is not a valid Expo push token`);
  }
  return {
    to: pushToken,
    body: 'This is a test notification',
    badge: 2,
    data: { withSome: 'data' },
    richContent: {
      image: 'https://example.com/statics/some-image-here-if-you-want.jpg'
    },
  };
